def run_agent(plan, max_steps=4):
    trace = []
    for i, action in enumerate(plan, 1):
        if i > max_steps:
            trace.append(("halt", "max_steps"))
            break
        trace.append((i, action))
        if action == "stop":
            break
    else:
        if not plan:
            trace.append((1, "stop"))
    return trace

print(run_agent(["search", "calc", "stop"]))
print(run_agent([]))
print(run_agent(["search", "search", "search", "search", "search"]))

def run_agent(plan, max_steps=5):
    trace, history = [], []
    for i, action in enumerate(plan, 1):
        if i > max_steps:
            trace.append(("halt", "max_steps"))
            break
        if history.count(action) >= 1 and action != "stop":
            trace.append(("halt", f"repeated action: {action}"))
            break
        history.append(action)
        trace.append((i, action))
        if action == "stop":
            break
    return trace

print(run_agent(["search", "search", "finish"]))
print(run_agent(["search", "calc", "stop"], max_steps=4))

import json

def call_tool(name, payload):
    schema = {"query": (str, None, None), "top_k": (int, 1, 10)}
    problems = []
    for key, (typ, lo, hi) in schema.items():
        if key not in payload:
            problems.append(f"{key}: missing")
        elif not isinstance(payload[key], typ) or isinstance(payload[key], bool):
            problems.append(f"{key}: expected {typ.__name__}")
        elif lo is not None and not (lo <= payload[key] <= hi):
            problems.append(f"{key}: out of range")
    if problems:
        return {"ok": False, "errors": problems}
    return {"ok": True, "result": f"ran {name} with {payload['top_k']} results"}

print(call_tool("search", {"query": "rag", "top_k": 5}))
print(call_tool("search", {"query": "rag", "top_k": 99}))
print(json.dumps(call_tool("search", {"top_k": "5"})))
